const music=document.createElement('audio');music.src='/bamboo.ogg';music.loop=true;music.preload='none';const savedVolume=localStorage.getItem('zen-music-volume');music.volume=savedVolume===null?.35:Math.max(0,Math.min(1,Number(savedVolume)||0));const player=document.createElement('aside');player.className='zen-music';player.setAttribute('aria-label','Nhạc nền');player.innerHTML='<button type="button" class="music-toggle" aria-label="Phát nhạc nền" aria-pressed="false"><svg class="music-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/></svg><span>Nhạc nền</span><i class="music-state-dot" aria-hidden="true"></i></button><details><summary aria-label="Điều chỉnh nhạc nền"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16M4 16h16"/><circle cx="9" cy="8" r="3"/><circle cx="15" cy="16" r="3"/></svg></summary><label><span>Âm lượng</span><strong>'+Math.round(music.volume*100)+'%</strong><small>Lotus at First Light</small><input type="range" min="0" max="100" value="'+Math.round(music.volume*100)+'" aria-label="Âm lượng nhạc nền"></label><p role="status"></p></details>';document.body.append(player);const toggle=player.querySelector('button');function paintMusic(){const playing=!music.paused;toggle.setAttribute('aria-pressed',String(playing));toggle.setAttribute('aria-label',playing?'Tạm dừng nhạc nền':'Phát nhạc nền');player.dataset.playing=String(playing);}toggle.onclick=async()=>{if(!music.paused)music.pause();else try{await music.play();}catch{player.querySelector('p').textContent='Chưa phát được nhạc. Bấm để thử lại.';}paintMusic();};music.onpause=music.onplay=paintMusic;player.querySelector('input').oninput=e=>{music.volume=Number(e.target.value)/100;localStorage.setItem('zen-music-volume',String(music.volume));player.querySelector('strong').textContent=e.target.value+'%';};let musicFrame=false;function contrastMusic(){musicFrame=false;const r=player.getBoundingClientRect(),elements=document.elementsFromPoint(Math.max(0,r.left-8),Math.max(0,r.top));let rgb;for(const el of elements){if(player.contains(el))continue;const c=getComputedStyle(el).backgroundColor.match(/[\d.]+/g);if(c&&c.length>=3&&(c.length<4||Number(c[3])>.8)){rgb=c.map(Number);break;}}const light=!rgb||(rgb[0]*.299+rgb[1]*.587+rgb[2]*.114)>145;player.dataset.surface=light?'light':'dark';}window.addEventListener('scroll',()=>{if(!musicFrame){musicFrame=true;requestAnimationFrame(contrastMusic);}},{passive:true});contrastMusic();
const authVersion=document.createElement('a');authVersion.className='auth-version';authVersion.href='#';authVersion.textContent='v'+APP_VERSION;authVersion.setAttribute('aria-label','Phiên bản '+APP_VERSION);document.body.append(authVersion);authVersion.onclick=e=>{e.preventDefault();notify('Kanban Zen Studio · '+authVersion.textContent);};async function updateAuthVersion(){if(document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});const v=(await r.json()).version;if(/^\d+\.\d+\.\d+$/.test(v)){authVersion.textContent='v'+v;authVersion.setAttribute('aria-label','Phiên bản '+v);}}catch{}}updateAuthVersion();setInterval(updateAuthVersion,60000);
